let currentStep = 1; let formData = {}; // Modal elementlerini al const customAlertModal = document.getElementById('customAlertModal'); const customAlertModalMessage = document.getElementById('customAlertModalMessage'); const customAlertModalTitle = document.getElementById('customAlertModalTitle'); // Başlık için // File upload handler document.getElementById('cvFile').addEventListener('change', function(e) { const fileName = e.target.files[0] ? e.target.files[0].name : '{% trans "Click to upload file" %}'; document.getElementById('file-name').textContent = fileName; }); // Yeni Modal Fonksiyonları function showCustomAlertModal(message, title = '{% trans "Notification" %}') { customAlertModalTitle.textContent = title; customAlertModalMessage.textContent = message; customAlertModal.style.display = 'flex'; // Flex ile ortalamak için setTimeout(() => { // CSS geçişi için küçük bir gecikme customAlertModal.classList.add('show'); }, 10); } function hideCustomAlertModal() { customAlertModal.classList.remove('show'); setTimeout(() => { // CSS geçişinin bitmesini bekle customAlertModal.style.display = 'none'; }, 300); // CSS transition süresiyle eşleşmeli } // Modalın dışına tıklandığında kapatma customAlertModal.addEventListener('click', function(event) { if (event.target === customAlertModal) { // Eğer tıklanan yer overlay ise hideCustomAlertModal(); } }); function nextStep(step) { if (validateStep(step)) { saveStepData(step); showStep(step + 1); } } function previousStep(step) { showStep(step - 1); } function showStep(stepNumber) { document.querySelectorAll('.step-container').forEach(container => { container.style.display = 'none'; }); const targetStepId = stepNumber <= 3 ? `step-${stepNumber}` : (stepNumber === 4 ? 'confirmation' : 'success'); const targetStepElement = document.getElementById(targetStepId); if (targetStepElement) { targetStepElement.style.display = 'block'; } currentStep = stepNumber; } function validateStep(step) { let isValid = true; let errorMessage = ''; let errorTitle = '{% trans "Validation Error" %}'; // Hata başlığı if (step === 1) { const firstName = document.getElementById('firstName').value.trim(); const lastName = document.getElementById('lastName').value.trim(); const email = document.getElementById('email').value.trim(); const phone = document.getElementById('phone').value.trim(); if (!firstName || !lastName || !email || !phone) { isValid = false; errorMessage = '{% trans "Please fill in all required personal information fields." %}'; } else if (!/^\S+@\S+\.\S+$/.test(email)) { // Basit e-posta format kontrolü isValid = false; errorMessage = '{% trans "Please enter a valid email address." %}'; } } else if (step === 2) { const cvFile = document.getElementById('cvFile').files[0]; if (!cvFile) { isValid = false; errorMessage = '{% trans "Please upload your CV file." %}'; } } else if (step === 3) { const motivationLetter = document.getElementById('motivationLetter').value.trim(); if (!motivationLetter) { isValid = false; errorMessage = '{% trans "Please write your motivation letter." %}'; } } if (!isValid) { // alert(errorMessage); // ESKİ YÖNTEM showCustomAlertModal(errorMessage, errorTitle); // YENİ YÖNTEM } return isValid; } function saveStepData(step) { if (step === 1) { formData.first_name = document.getElementById('firstName').value.trim(); formData.last_name = document.getElementById('lastName').value.trim(); formData.email = document.getElementById('email').value.trim(); formData.phone = document.getElementById('phone').value.trim(); } else if (step === 2) { formData.cv_file = document.getElementById('cvFile').files[0]; } else if (step === 3) { formData.motivation_letter = document.getElementById('motivationLetter').value.trim(); } } function showConfirmation() { if (validateStep(3)) { // Önce 3. adımı doğrula saveStepData(3); // 3. adım verilerini kaydet document.getElementById('confirm-firstName').textContent = formData.first_name; document.getElementById('confirm-lastName').textContent = formData.last_name; document.getElementById('confirm-email').textContent = formData.email; document.getElementById('confirm-phone').textContent = formData.phone; document.getElementById('confirm-cvFile').textContent = formData.cv_file ? formData.cv_file.name : '{% trans "Not uploaded" %}'; showStep(4); // Onay adımını göster } } function submitApplication() { const submitFormData = new FormData(); // CSRF token'ını form içinden almak daha güvenli olabilir, ama bu da çalışır. const csrfTokenInput = document.querySelector('#step1-form [name=csrfmiddlewaretoken]') || document.querySelector('#step2-form [name=csrfmiddlewaretoken]') || document.querySelector('#step3-form [name=csrfmiddlewaretoken]'); if (csrfTokenInput) { submitFormData.append('csrfmiddlewaretoken', csrfTokenInput.value); } else { console.error('CSRF token not found!'); showCustomAlertModal('{% trans "A security token is missing. Please refresh the page and try again." %}', '{% trans "Error" %}'); return; } submitFormData.append('first_name', formData.first_name); submitFormData.append('last_name', formData.last_name); submitFormData.append('email', formData.email); submitFormData.append('phone', formData.phone); if (formData.cv_file) { // CV dosyası varsa ekle submitFormData.append('cv_file', formData.cv_file); } submitFormData.append('motivation_letter', formData.motivation_letter); // Butonu geçici olarak devre dışı bırak ve yükleniyor metni ekle const confirmButton = document.querySelector('.btn-confirm'); const originalButtonText = confirmButton.innerHTML; confirmButton.disabled = true; confirmButton.innerHTML = '{% trans "Sending..." %}'; fetch(window.location.href, { // Mevcut sayfanın URL'sine POST yapılıyor method: 'POST', body: submitFormData // 'Content-Type': 'multipart/form-data' başlığı FormData ile otomatik ayarlanır }) .then(response => response.json()) .then(data => { if (data.success) { showStep(5); // Başarı adımını göster } else { // alert(data.message); // ESKİ YÖNTEM showCustomAlertModal(data.message || '{% trans "An unknown error occurred. Please check your input." %}', '{% trans "Application Error" %}'); // YENİ YÖNTEM } }) .catch(error => { console.error('Error:', error); // alert('{% trans "An error occurred while submitting your application. Please try again." %}'); // ESKİ YÖNTEM showCustomAlertModal('{% trans "An error occurred while submitting your application. Please try again later." %}', '{% trans "Submission Failed" %}'); // YENİ YÖNTEM }) .finally(() => { // Butonu tekrar etkinleştir ve orijinal metni geri yükle confirmButton.disabled = false; confirmButton.innerHTML = originalButtonText; }); } document.addEventListener('DOMContentLoaded', function() { showStep(1); // Sayfa yüklendiğinde ilk adımı göster });